using System.Security.Claims;using LocalPro.Web.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;[Authorize]public class SafetyModel(AppDbContext db):PageModel{public List<(int Id,string Name)> Items{get;set;}=[];public async Task OnGetAsync(){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var list=await(from b in db.Blocks join u in db.Users on b.BlockedUserId equals u.Id where b.UserId==id select new{b.Id,u.DisplayName}).ToListAsync();Items=list.Select(x=>(x.Id,string.IsNullOrEmpty(x.DisplayName)?"Blocked account":x.DisplayName)).ToList();}public async Task<IActionResult> OnPostAsync(int block){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;var b=await db.Blocks.SingleOrDefaultAsync(b=>b.Id==block&&b.UserId==id);if(b!=null){db.Remove(b);await db.SaveChangesAsync();}return RedirectToPage();}}
